package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.escalation.InvalidAddressException;

/**
 * Normalizes a new owner's address to its canonical stored form (see {@link AddressNormalizer}):
 * trims and collapses whitespace, upper-cases and expands common street-type abbreviations, so
 * {@code "  12  main  st "} is stored as {@code "12 MAIN STREET"}. The stored (and later returned)
 * value is the normalized string. Enforces the required-field rule against that normalized form:
 * an address that is blank once normalized is a 400. Mutates the built {@link Owner} in place so
 * {@link SaveOwner} persists the normalized value and the later household steps compare it.
 */
public class NormalizeOwnerAddress {

    public void service(@Val Owner owner) throws InvalidAddressException {
        String normalized = AddressNormalizer.normalize(owner.getAddress());
        if (normalized == null) {
            throw new InvalidAddressException("Address must not be blank after normalization");
        }
        owner.setAddress(normalized);
    }
}
===== AddressNormalizer.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

/**
 * Canonical form for an owner's postal address, applied on create. Trims and collapses
 * runs of whitespace to a single space, upper-cases, and expands common street-type
 * abbreviations ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) as whole
 * tokens (a single trailing {@code '.'} is ignored, so {@code "St."} also expands). So
 * {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
 *
 * <p>Every comparison of addresses (household duplicate detection and the shared household
 * id) canonicalizes both sides through {@link #normalize(String)} so they use the same
 * normalized form. Returns {@code null} when the value is blank after normalization.
 */
final class AddressNormalizer {

    private static final Map<String, String> ABBREVIATIONS = Map.of(
            "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");

    private AddressNormalizer() {
    }

    /**
     * Normalize an address to its canonical stored form, or {@code null} when the value is
     * {@code null} or blank once trimmed.
     */
    static String normalize(String value) {
        if (value == null) {
            return null;
        }
        String collapsed = value.trim().replaceAll("\\s+", " ");
        if (collapsed.isEmpty()) {
            return null;
        }
        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            String token = tokens[i];
            String key = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
            String expanded = ABBREVIATIONS.get(key);
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(expanded != null ? expanded : token);
        }
        return sb.toString();
    }
}
